			+ "inventory, equipment, bank, rune pouch, seed vault, quiver and group storage. "
			+ "AUTO sends this only while the official Group Ironmen Tracker plugin is not "
			+ "running, so the two never upload competing copies. OFF never sends anything, and "
			+ "the plugin only reads.",
		position = 0,
		section = uploadSection
	)
	default UploadMode uploadMode()
	{
		return UploadMode.AUTO;
	}

	enum UploadMode
	{
		AUTO,
		OFF
	}

	/** Where the Skills tab hover panel is anchored. */
	enum SkillHoverPosition
	{
		/** Beside the Skills tab, preferring its left so it clears the right edge. */
		AUTO,
		LEFT,
		RIGHT,
		SCREEN_CENTRE
	}
}

package com.groupironmencompanion.api;

/**
 * One element of the {@code get-group-data} response.
 * <p>
 * Field names deliberately match the server's snake_case JSON keys so Gson binds them
 * without any custom naming policy or type tokens. Any field the server omitted because it
 * has not changed since {@code from_time} arrives as null and must be treated as
 * "no new data", not as "cleared".
 */
public class MemberDto
{
	public String name;

	/** [hitpoints, maxHitpoints, prayer, maxPrayer, runEnergy, maxRunEnergy, world] */
	public int[] stats;

	/** [x, y, plane, onBoat] */
	public int[] coordinates;

	/** Experience per skill, indexed by {@code GroupSkill.ordinal()}. */
	public int[] skills;

	public int[] quests;
	public int[] diary_vars;

	/** Flat [itemId, quantity, itemId, quantity, ...] pairs. */
	public int[] inventory;
	public int[] equipment;
	public int[] bank;
	public int[] shared_bank;
	public int[] rune_pouch;
	public int[] seed_vault;
	public int[] quiver;
	public int[] potion_storage;
	public int[] deposited;

	public InteractingDto interacting;

	/** RFC 3339 timestamp of this member's most recent change. */
	public String last_updated;

	public static class InteractingDto
	{
		public String name;
		public int scale;
		public int ratio;
		public CoordinatesDto location;
		public String last_updated;
	}

	public static class CoordinatesDto
	{
		public int x;
		public int y;
		public int plane;
	}
}

package com.groupironmencompanion.api;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.ConfigManager;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the groupiron.men API, or to a self-hosted instance of it.
 * <p>
 * Every request goes to the base URL the user configured and carries the group token the
 * user supplied. Nothing is sent anywhere else, and no data leaves the client at all unless
 * the fallback uploader is explicitly active.
 * <p>
 * The shared RuneLite HTTP client is reused for its connection pool, but with redirects
 * disabled and a hard call timeout. Redirects matter because the base URL is user-supplied
 * and requests carry a bearer token: a redirect could otherwise hand that token to a host
 * the user never configured. The timeout matters because a hung server would otherwise pin
 * the polling thread indefinitely.
 */
@Slf4j
@Singleton
public class GroupApi
{
	public static final String PUBLIC_BASE_URL = "https://groupiron.men";

	/** Config group of the official tracker plugin, read so credentials need entering once. */
	private static final String TRACKER_CONFIG_GROUP = "GroupIronmenTracker";

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String USER_AGENT =
		"GroupIronmenCompanion/1.0.0 RuneLite/" + RuneLiteProperties.getVersion();

	private static final int CALL_TIMEOUT_SECONDS = 20;

	/** Guards against a hostile or broken server returning an unbounded body. */
	private static final long MAX_RESPONSE_BYTES = 8L * 1024 * 1024;

	@Inject
	private OkHttpClient sharedClient;

	@Inject
	private Gson gson;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private ConfigManager configManager;

	private volatile OkHttpClient client;

	private OkHttpClient client()
	{
		OkHttpClient local = client;
		if (local == null)
		{
			synchronized (this)
			{
				local = client;
				if (local == null)
				{
					client = local = sharedClient.newBuilder()
						.followRedirects(false)
						.followSslRedirects(false)
						.callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
						.build();
				}
			}
		}
		return local;
	}

	// ------------------------------------------------------------------
	// Credentials
	// ------------------------------------------------------------------

	public String getBaseUrl()
	{
		String override = config.baseUrlOverride().trim();
		if (override.isEmpty())
		{
			// A group that self-hosts and only configured the official tracker plugin would
			// otherwise be sent to the public server, so inherit its override too.
			override = trackerConfig("baseUrlOverride");
		}
		if (override.isEmpty())
		{
			return PUBLIC_BASE_URL;
		}
		// Strip a trailing slash so URL building stays predictable.
		return override.endsWith("/") ? override.substring(0, override.length() - 1) : override;
	}

	/**
	 * The group name to use, preferring this plugin's own setting and falling back to the
	 * official tracker plugin's configuration so an existing setup works out of the box.
	 */
	public String getGroupName()
	{
		String own = config.groupName().trim();
		return own.isEmpty() ? trackerConfig("groupName") : own;
	}

	public String getGroupToken()
	{
		String own = config.groupToken().trim();
		return own.isEmpty() ? trackerConfig("groupToken") : own;
	}

	private String trackerConfig(String key)
	{
		try
		{
			String value = configManager.getConfiguration(TRACKER_CONFIG_GROUP, key);
			return value == null ? "" : value.trim();
		}
		catch (Exception e)
		{
			log.debug("Could not read tracker plugin config key {}", key, e);
			return "";
		}
	}

	public boolean hasCredentials()
	{
		return !getGroupName().isEmpty() && !getGroupToken().isEmpty();
	}

	// ------------------------------------------------------------------
	// URL building
	// ------------------------------------------------------------------

	/**
	 * Builds a group endpoint URL. The group name goes in as a path segment rather than
	 * being concatenated, so names containing spaces or other reserved characters are
	 * encoded correctly and cannot alter the shape of the path.
	 */
	@Nullable
	private HttpUrl.Builder endpoint(String groupName, String action)
	{
		HttpUrl base = HttpUrl.parse(getBaseUrl());
		if (base == null)
		{
			log.warn("Group Ironmen Companion: the configured server URL is not a valid URL");
			return null;
		}
		return base.newBuilder()
			.addPathSegment("api")
			.addPathSegment("group")
			.addPathSegment(groupName)
			.addPathSegment(action);
	}

	private Request.Builder authorised(HttpUrl url, String token)
	{
		return new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.header("Accept", "application/json")
			.header("Authorization", token);
	}

	// ------------------------------------------------------------------
	// Requests
	// ------------------------------------------------------------------

	/**
	 * Fetches everything that changed since {@code fromTime}.
	 *
	 * @return the members array, or null when the request failed
	 * @throws NotAuthorisedException when the server rejected the token
	 */
	@Nullable
	public MemberDto[] getGroupData(String fromTime) throws NotAuthorisedException
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty())
		{
			return null;
		}

		HttpUrl.Builder builder = endpoint(groupName, "get-group-data");
		if (builder == null)
		{
			return null;
		}
		HttpUrl url = builder.addQueryParameter("from_time", fromTime).build();

		try (Response response = client().newCall(authorised(url, token).get().build()).execute())
		{
			if (response.code() == 401 || response.code() == 403)
			{
				throw new NotAuthorisedException();
			}
			if (!response.isSuccessful())
			{
				log.debug("get-group-data returned {}", response.code());
				return null;
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				return null;
			}
			// A declared length is only present when the server does not use chunked
			// encoding, and most do, so the stream itself has to be bounded rather than
			// trusting contentLength. Reading past the cap fails the parse instead of
			// letting an unbounded body allocate without limit.
			Reader reader = new InputStreamReader(
				new BoundedInputStream(body.byteStream(), MAX_RESPONSE_BYTES), StandardCharsets.UTF_8);
			return gson.fromJson(reader, MemberDto[].class);
		}
		catch (JsonSyntaxException e)
		{
			// Deliberately does not log the body: it is attacker-influenced and large.
			log.warn("Group Ironmen Companion: the server response was not valid JSON");
			return null;
		}
		catch (IOException e)
		{
			log.debug("get-group-data failed: {}", e.toString());
			return null;
		}
	}

	/** Checks that the given character is a member of the configured group. */
	public boolean isPlayerInGroup(String playerName)
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty() || playerName == null)
		{
			return false;
		}

		HttpUrl.Builder builder = endpoint(groupName, "am-i-in-group");
		if (builder == null)
		{
			return false;
		}
		HttpUrl url = builder.addQueryParameter("member_name", playerName).build();

		try (Response response = client().newCall(authorised(url, token).get().build()).execute())
		{
			return response.isSuccessful();
		}
		catch (IOException e)
		{
			log.debug("am-i-in-group failed: {}", e.toString());
			return false;
		}
	}

	/**
	 * Posts a member update. Only ever called by the fallback uploader, and only when the
	 * official tracker plugin is not running.
	 *
	 * @return true when the server accepted the update
	 * @throws NotAuthorisedException when the server rejected the token
	 */
	public boolean updateGroupMember(Object payload) throws NotAuthorisedException
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty())
		{
			return false;
		}

		HttpUrl.Builder builder = endpoint(groupName, "update-group-member");
		if (builder == null)
		{
			return false;
		}

		RequestBody body = RequestBody.create(JSON, gson.toJson(payload));
		try (Response response = client().newCall(authorised(builder.build(), token).post(body).build()).execute())
		{
			if (response.code() == 401 || response.code() == 403)
			{
				throw new NotAuthorisedException();
			}
			return response.isSuccessful();
		}
		catch (IOException e)
		{
			log.debug("update-group-member failed: {}", e.toString());
			return false;
		}
	}

	/** Fails the read once more than {@code limit} bytes have been consumed. */
	private static final class BoundedInputStream extends InputStream
	{
		private final InputStream delegate;
		private final long limit;
		private long read;

		BoundedInputStream(InputStream delegate, long limit)
		{
			this.delegate = delegate;
			this.limit = limit;
		}

		@Override
		public int read() throws IOException
		{
			int value = delegate.read();
			if (value >= 0)
			{
				count(1);
			}
			return value;
		}

		@Override
		public int read(byte[] buffer, int offset, int length) throws IOException
		{
			int got = delegate.read(buffer, offset, length);
			if (got > 0)
			{
				count(got);
			}
			return got;
		}

		private void count(int bytes) throws IOException
		{
			read += bytes;
			if (read > limit)
			{
				throw new IOException("response exceeded " + limit + " bytes");
			}
		}

		@Override
		public void close() throws IOException
		{
			delegate.close();
		}
	}

	/** Raised when the server rejects the configured group token. */
	public static class NotAuthorisedException extends Exception
	{
		public NotAuthorisedException()
		{
			super("The group name or token was rejected by the server");
		}
	}
}

package com.groupironmencompanion.route;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

/**
 * Keeps a Shortest Path route pointed at a moving group member.
 * <p>
 * The target is stored as a member name rather than a fixed point, so as their position
 * updates the route is re-issued to follow them. It is retargeted only when they have
 * actually moved a meaningful distance, because re-pathing costs a search and their
 * coordinates jitter by a tile as they walk.
 * <p>
 * Arrival is judged against the member's <em>true</em> position, including plane, not the
 * surface entrance drawn on the overworld map: following someone into a dungeon should not
 * count as done the moment you reach the ladder.
 */
@Singleton
public class RouteTracker
{
	/** How far the target must move before the route is recalculated, in tiles. */
	private static final int RETARGET_DISTANCE = 8;

	/** How close counts as having arrived, in tiles. */
	private static final int ARRIVAL_DISTANCE = 3;

	@Inject
	private Client client;

	@Inject
	private GroupState groupState;

	@Inject
	private ShortestPathBridge bridge;

	private volatile String targetName;
	private WorldPoint lastRouted;

	/** The member currently being routed to, or null when no route is active. */
	@Nullable
	public String getTargetName()
	{
		return targetName;
	}

	public boolean isRoutingTo(GroupMember member)
	{
		return member != null && GroupState.namesMatch(targetName, member.getName());
	}

	/** Starts routing to a member, or stops if they were already the target. */
	public void toggle(GroupMember member)
	{
		if (member == null)
		{
			return;
		}
		if (isRoutingTo(member))
		{
			stop();
			return;
		}

		targetName = member.getName();
		lastRouted = null;
		update();
	}

	public void stop()
	{
		if (targetName == null)
		{
			return;
		}
		targetName = null;
		lastRouted = null;
		bridge.clear();
	}

	/**
	 * Re-points the route at the target's latest position, and ends it on arrival. Safe to
	 * call every tick; it only talks to Shortest Path when something has actually changed.
	 * Must run on the client thread.
	 */
	public void update()
	{
		String name = targetName;
		if (name == null)
		{
			return;
		}

		GroupMember member = groupState.getMember(name);
		if (member == null)
		{
			// They left the group, so there is nothing left to follow.
			stop();
			return;
		}

		WorldPoint target = member.getWorldPoint();
		if (target == null)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		WorldPoint here = local == null ? null : local.getWorldLocation();
		if (here != null && here.getPlane() == target.getPlane()
			&& here.distanceTo2D(target) <= ARRIVAL_DISTANCE)
		{
			stop();
			return;
		}

		if (lastRouted == null || lastRouted.distanceTo2D(target) > RETARGET_DISTANCE
			|| lastRouted.getPlane() != target.getPlane())
		{
			lastRouted = target;
			bridge.pathTo(target);
		}
	}
}

package com.groupironmencompanion.route;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Drives the Shortest Path plugin.
 * <p>
 * Hub plugins each get their own classloader, so this cannot compile against
 * {@code shortestpath.ShortestPathPlugin} or cast it, and reflection is forbidden.
 * RuneLite's answer is {@link PluginMessage}: a namespaced event carrying a plain data map.
 * Everything crossing the boundary is either a JDK type or {@link WorldPoint}, which lives in
 * runelite-api on the shared parent classloader, so both sides agree on it. No dependency is
 * added to the build.
 * <p>
 * Contract, from Shortest Path's {@code onPluginMessage}:
 * <pre>
 *   namespace "shortestpath"
 *   name      "path"   data { "start": WorldPoint|Integer|null,
 *                             "target": WorldPoint|Integer|Set,
 *                             "config": Map&lt;String,Object&gt; }
 *   name      "clear"  data {}
 * </pre>
 * If Shortest Path is not installed then nothing subscribes to the event and the post is a
 * harmless no-op, so this degrades gracefully by construction.
 */
@Slf4j
@Singleton
public class ShortestPathBridge
{
	private static final String NAMESPACE = "shortestpath";
	private static final String MESSAGE_PATH = "path";
	private static final String MESSAGE_CLEAR = "clear";

	private static final String KEY_START = "start";
	private static final String KEY_TARGET = "target";

	private final EventBus eventBus;

	@Inject
	public ShortestPathBridge(EventBus eventBus)
	{
		this.eventBus = eventBus;
	}

	/**
	 * Paths from the player's current position to {@code target}. A null start lets Shortest
	 * Path use wherever the player happens to be.
	 */
	public void pathTo(WorldPoint target)
	{
		if (target == null)
		{
			return;
		}

		Map<String, Object> data = new HashMap<>();
		data.put(KEY_START, null);
		data.put(KEY_TARGET, target);

		log.debug("Requesting path to {}", target);
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_PATH, data));
	}

	/** Clears any path currently drawn. */
	public void clear()
	{
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_CLEAR));
	}
}

package com.groupironmencompanion.bank;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * A tooltip body that keeps the background colour it was given.
 * <p>
 * {@code TooltipOverlay} replaces the background of any {@link PanelComponent} tooltip with
 * the client's configured overlay colour, so setting one directly has no effect. Wrapping the
 * panel in a different type sidesteps that: the overlay sees something it does not recognise
 * as a panel, leaves it alone, and renders it as-is.
 */
class TintedTooltip implements LayoutableRenderableEntity
{
	private final PanelComponent panel;

	TintedTooltip(PanelComponent panel)
	{
		this.panel = panel;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		return panel.render(graphics);
	}

	@Override
	public Rectangle getBounds()
	{
		return panel.getBounds();
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		panel.setPreferredLocation(position);
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		panel.setPreferredSize(dimension);
	}
}

package com.groupironmencompanion.bank;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Draws the read-only group bank window.
 * <p>
 * The window is entirely the plugin's own drawing. It is not a game interface, it never
 * modifies, hides, resizes or reparents any game widget, and it creates no menu entries. It
 * cannot move items: there is no withdraw, deposit, or any other action on anything shown,
 * because the plugin only ever has item ids and quantities read back from your group's
 * server.
 */
@Singleton
public class GroupBankOverlay extends Overlay
{
	static final int CELL_WIDTH = 40;
	static final int CELL_HEIGHT = 36;
	static final int VISIBLE_ROWS = 7;

	private static final int PADDING = 8;
	private static final int TITLE_HEIGHT = 22;
	private static final int TAB_HEIGHT = 20;
	private static final int SEARCH_HEIGHT = 20;
	private static final int FOOTER_HEIGHT = 18;
	private static final int SCROLLBAR_WIDTH = 6;

	/** Height for a window whose tab strip occupies the given number of rows. */
	private static int heightFor(int tabRows)
	{
		return TITLE_HEIGHT + tabRows * TAB_HEIGHT + SEARCH_HEIGHT
			+ VISIBLE_ROWS * CELL_HEIGHT + FOOTER_HEIGHT + PADDING;
	}

	/** Rows the tab strip needed when it was last laid out. */
	private volatile int tabRows = 1;

	static final int WIDTH =
		PADDING * 2 + GroupBankViewer.COLUMNS * CELL_WIDTH + SCROLLBAR_WIDTH;

	private static final Font TAB_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);
	private static final Font QUANTITY_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 11);

	/** Matches the skills hover panel, which is dark enough to stay readable over the bank. */
	private static final Color TOOLTIP_BACKGROUND = new Color(22, 19, 15, 235);

	@Inject
	private Client client;

	@Inject
	private GroupBankViewer viewer;

	@Inject
	private GroupState groupState;

	@Inject
	private ItemManager itemManager;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private TooltipManager tooltipManager;

	/**
	 * Hit boxes in canvas coordinates, rebuilt on the client thread every frame and read on
	 * the AWT thread by {@link GroupBankInput}. Published as one immutable snapshot so the
	 * input handler can never observe a half-built frame or iterate a list being rewritten.
	 */
	private volatile HitBoxes hits = HitBoxes.EMPTY;

	/** Accumulates this frame's hit boxes before they are published. */
	private List<TabHit> frameTabs = new ArrayList<>();
	private Rectangle frameClose = new Rectangle();
	private Rectangle frameSearch = new Rectangle();
	private Rectangle frameGrid = new Rectangle();
	private Rectangle frameScrollbar = new Rectangle();

	@Inject
	public GroupBankOverlay()
	{
		// DYNAMIC positions the window purely from its preferred location; setMovable must
		// come after setPosition, which resets it.
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(true);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public Dimension getWindowSize()
	{
		return new Dimension(WIDTH, heightFor(tabRows));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.bankViewer() || !viewer.isOpen())
		{
			hits = HitBoxes.EMPTY;
			return null;
		}

		viewer.rebuildIfNeeded();

		java.awt.Point origin = getBounds().getLocation();
		Point mouse = client.getMouseCanvasPosition();
		java.awt.Point local = mouse == null
			? new java.awt.Point(-1, -1)
			: new java.awt.Point(mouse.getX() - origin.x, mouse.getY() - origin.y);

		frameTabs = new ArrayList<>();

		// Tabs are laid out before anything is drawn, because how many rows they need
		// decides how tall the window is.
		graphics.setFont(TAB_FONT);
		List<List<TabSlot>> layout = layoutTabs(graphics.getFontMetrics(), viewer.getTabs());
		tabRows = Math.max(1, layout.size());
		int height = heightFor(tabRows);

		drawFrame(graphics, height);
		int y = drawTitle(graphics, origin, local);
		y = drawTabs(graphics, origin, y, local, layout);
		y = drawSearch(graphics, origin, y, local);
		drawGrid(graphics, origin, y, local);
		drawFooter(graphics, height);

		hits = new HitBoxes(
			new Rectangle(origin.x, origin.y, WIDTH, height),
			frameClose, frameSearch, frameGrid, frameScrollbar, frameTabs);

		return new Dimension(WIDTH, height);
	}

	// ------------------------------------------------------------------
	// Drawing
	// ------------------------------------------------------------------

	private void drawFrame(Graphics2D graphics, int height)
	{
		graphics.setColor(BankStyle.BACKGROUND);
		graphics.fillRect(0, 0, WIDTH, height);
		graphics.setColor(BankStyle.BORDER);
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawRect(0, 0, WIDTH - 1, height - 1);
	}

	private int drawTitle(Graphics2D graphics, java.awt.Point origin, java.awt.Point local)
	{
		graphics.setColor(BankStyle.TITLE_BACKGROUND);
		graphics.fillRect(1, 1, WIDTH - 2, TITLE_HEIGHT - 1);

		graphics.setColor(BankStyle.TEXT);
		graphics.setFont(TAB_FONT.deriveFont(Font.BOLD, 12f));
		graphics.drawString("Group Bank  (view only)", PADDING, 15);

		Rectangle close = new Rectangle(WIDTH - 20, 4, 14, 14);
		boolean hovered = close.contains(local);
		graphics.setColor(hovered ? Color.WHITE : BankStyle.TEXT_DIM);
		graphics.setFont(TAB_FONT.deriveFont(Font.BOLD, 12f));
		graphics.drawString("x", close.x + 5, close.y + 11);

		frameClose = toCanvas(close, origin);
		return TITLE_HEIGHT;
	}

	/**
	 * Arranges the tabs into rows that fit the window's width.
	 * <p>
	 * They used to be drawn on a single strip, and anything past the right edge was simply
	 * dropped. With a full group that silently swallowed the last tab, which is how the
	 * group storage tab became unreachable. Wrapping keeps every tab clickable.
	 */
	private List<List<TabSlot>> layoutTabs(FontMetrics metrics, List<String> tabs)
	{
		List<List<TabSlot>> rows = new ArrayList<>();
		if (tabs.isEmpty())
		{
			return rows;
		}

		int available = WIDTH - PADDING * 2;
		List<TabSlot> row = new ArrayList<>();
		int x = PADDING;

		for (String tab : tabs)
		{
			String label = abbreviate(tab, metrics, 96);
			int width = Math.min(available, metrics.stringWidth(label) + 12);

			if (x > PADDING && x + width > available + PADDING)
			{
				rows.add(row);
				row = new ArrayList<>();
				x = PADDING;
			}

			row.add(new TabSlot(tab, label, x, width));
			x += width + 2;
		}

		if (!row.isEmpty())
		{
			rows.add(row);
		}
		return rows;
	}

	private int drawTabs(Graphics2D graphics, java.awt.Point origin, int top,
		java.awt.Point local, List<List<TabSlot>> layout)
	{
		graphics.setFont(TAB_FONT);

		int y = top;
		for (List<TabSlot> row : layout)
		{
			for (TabSlot slot : row)
			{
				Rectangle rect = new Rectangle(slot.x, y + 2, slot.width, TAB_HEIGHT - 4);
				boolean active = slot.tab.equals(viewer.getActiveTab());

				graphics.setColor(active ? BankStyle.TAB_ACTIVE : BankStyle.TAB_IDLE);
				graphics.fillRect(rect.x, rect.y, rect.width, rect.height);

				if (rect.contains(local) && !active)
				{
					graphics.setColor(BankStyle.HOVER);
					graphics.fillRect(rect.x, rect.y, rect.width, rect.height);
				}

				graphics.setColor(active ? Color.WHITE : colourForTab(slot.tab));
				graphics.drawString(slot.label, rect.x + 6, rect.y + rect.height - 5);

				frameTabs.add(new TabHit(slot.tab, toCanvas(rect, origin)));
			}
			y += TAB_HEIGHT;
		}

		return Math.max(y, top + TAB_HEIGHT);
	}

	/** One tab's place on its row, worked out before anything is drawn. */
	private static final class TabSlot
	{
		private final String tab;
		private final String label;
		private final int x;
		private final int width;

		TabSlot(String tab, String label, int x, int width)
		{
			this.tab = tab;
			this.label = label;
			this.x = x;
			this.width = width;
		}
	}

	private int drawSearch(Graphics2D graphics, java.awt.Point origin, int top, java.awt.Point local)
	{
		Rectangle rect = new Rectangle(PADDING, top + 1, WIDTH - PADDING * 2, SEARCH_HEIGHT - 4);

		graphics.setColor(BankStyle.SEARCH_BACKGROUND);
		graphics.fillRect(rect.x, rect.y, rect.width, rect.height);
		graphics.setColor(viewer.isSearchFocused() ? BankStyle.TEXT : BankStyle.BORDER);
		graphics.drawRect(rect.x, rect.y, rect.width, rect.height);

		graphics.setFont(TAB_FONT);
		String filter = viewer.getFilter();
		String text;
		Color colour;
		if (!filter.isEmpty())
		{
			text = filter + (viewer.isSearchFocused() && blink() ? "|" : "");
			colour = Color.WHITE;
		}
		else if (viewer.isSearchFocused())
		{
			text = blink() ? "|" : "";
			colour = Color.WHITE;
		}
		else
		{
			text = "Click here to search";
			colour = BankStyle.TEXT_DIM;
		}

		graphics.setColor(colour);
		graphics.drawString(text, rect.x + 5, rect.y + rect.height - 4);

		frameSearch = toCanvas(rect, origin);
		return top + SEARCH_HEIGHT;
	}

	private void drawGrid(Graphics2D graphics, java.awt.Point origin, int top, java.awt.Point local)
	{
		Rectangle area = new Rectangle(PADDING, top, GroupBankViewer.COLUMNS * CELL_WIDTH,
			VISIBLE_ROWS * CELL_HEIGHT);
		frameGrid = toCanvas(area, origin);

		List<GroupBankViewer.Row> rows = viewer.getRows();
		if (rows.isEmpty())
		{
			graphics.setColor(BankStyle.TEXT_DIM);
			graphics.setFont(TAB_FONT);
			String message = viewer.getFilter().isEmpty()
				? "No data yet. Check your group name and token."
				: "Nothing matches \"" + viewer.getFilter() + "\"";
			graphics.drawString(message, area.x + 4, area.y + 18);
			return;
		}

		java.awt.Shape clip = graphics.getClip();
		graphics.clipRect(area.x, area.y, area.width, area.height);

		int first = Math.min(viewer.getScrollRow(), Math.max(0, rows.size() - 1));
		int y = area.y;

		for (int index = first; index < rows.size() && y < area.y + area.height; index++)
		{
			GroupBankViewer.Row row = rows.get(index);

			if (row.isHeader())
			{
				graphics.setColor(BankStyle.TEXT);
				graphics.setFont(TAB_FONT.deriveFont(Font.BOLD));
				graphics.drawString(row.getHeader(), area.x + 2, y + 15);
				graphics.setColor(BankStyle.BORDER);
				graphics.drawLine(area.x + 2, y + 19, area.x + area.width - 4, y + 19);
				y += CELL_HEIGHT;
				continue;
			}

			int x = area.x;
			for (GroupBankViewer.Entry entry : row.getItems())
			{
				drawCell(graphics, entry, x, y, local);
				x += CELL_WIDTH;
			}
			y += CELL_HEIGHT;
		}

		graphics.setClip(clip);
		drawScrollbar(graphics, origin, area, rows.size(), first);
	}

	private void drawCell(Graphics2D graphics, GroupBankViewer.Entry entry, int x, int y, java.awt.Point local)
	{
		Rectangle cell = new Rectangle(x, y, CELL_WIDTH, CELL_HEIGHT);
		boolean hovered = cell.contains(local);

		if (hovered)
		{
			graphics.setColor(BankStyle.HOVER);
			graphics.fillRect(cell.x, cell.y, cell.width, cell.height);
		}

		long quantity = entry.getQuantity();

		// Always request the plain, quantity-1 sprite. Quantity is part of ItemManager's
		// image cache key and that cache holds only 128 entries, so asking for group-wide
		// totals would evict and re-render sprites every frame. The stack text is drawn
		// below instead, which also lets totals exceed what the game's own text renders.
		BufferedImage image = itemManager.getImage(entry.getItemId());
		if (image != null)
		{
			graphics.drawImage(image, x + (CELL_WIDTH - image.getWidth()) / 2,
				y + (CELL_HEIGHT - image.getHeight()) / 2, null);
		}

		if (quantity > 1)
		{
			graphics.setFont(QUANTITY_FONT);
			String label = BankStyle.shortQuantity(quantity);
			graphics.setColor(Color.BLACK);
			graphics.drawString(label, x + 3, y + 12);
			graphics.setColor(BankStyle.quantityColour(quantity));
			graphics.drawString(label, x + 2, y + 11);
		}

		if (hovered)
		{
			addTooltip(graphics, entry);
		}
	}

	private void drawScrollbar(Graphics2D graphics, java.awt.Point origin, Rectangle area,
		int totalRows, int firstRow)
	{
		if (totalRows <= VISIBLE_ROWS)
		{
			frameScrollbar = new Rectangle();
			return;
		}

		int x = area.x + area.width + 1;
		frameScrollbar = toCanvas(new Rectangle(x, area.y, SCROLLBAR_WIDTH - 2, area.height), origin);
		graphics.setColor(BankStyle.SEARCH_BACKGROUND);
		graphics.fillRect(x, area.y, SCROLLBAR_WIDTH - 2, area.height);

		int thumbHeight = Math.max(12, area.height * VISIBLE_ROWS / totalRows);
		int travel = area.height - thumbHeight;
		int maxScroll = Math.max(1, totalRows - VISIBLE_ROWS);
		int thumbY = area.y + (int) ((long) travel * Math.min(firstRow, maxScroll) / maxScroll);

		graphics.setColor(BankStyle.BORDER);
		graphics.fillRect(x, thumbY, SCROLLBAR_WIDTH - 2, thumbHeight);
	}

	private void drawFooter(Graphics2D graphics, int height)
	{
		graphics.setFont(TAB_FONT);
		graphics.setColor(BankStyle.TEXT_DIM);

		StringBuilder text = new StringBuilder();
		text.append(viewer.getVisibleItemCount()).append(" stacks");
		if (config.bankShowPrices())
		{
			text.append("  ·  ").append(BankStyle.gp(viewer.getVisibleValue()))
				.append(config.natureRuneCost() > 0 ? " alch profit" : " alch");
		}
		graphics.drawString(text.toString(), PADDING, height - 6);
	}

	// ------------------------------------------------------------------
	// Tooltip
	// ------------------------------------------------------------------

	private void addTooltip(Graphics2D graphics, GroupBankViewer.Entry entry)
	{
		String name = viewer.itemName(entry.getItemId());
		if (name == null)
		{
			return;
		}

		PanelComponent panel = new PanelComponent();
		panel.setPreferredSize(new Dimension(190, 0));
		panel.setBackgroundColor(TOOLTIP_BACKGROUND);
		panel.getChildren().add(TitleComponent.builder().text(name).color(Color.WHITE).build());

		panel.getChildren().add(LineComponent.builder()
			.left("Quantity")
			.leftColor(BankStyle.TEXT_DIM)
			.right(BankStyle.commas(entry.getQuantity()))
			.rightColor(BankStyle.quantityColour(entry.getQuantity()))
			.build());

		if (config.bankShowPrices())
		{
			long each = viewer.alchValue(entry.getItemId());
			panel.getChildren().add(LineComponent.builder()
				.left("Alchs for")
				.leftColor(BankStyle.TEXT_DIM)
				.right(BankStyle.commas(each) + " ea")
				.rightColor(BankStyle.TEXT_DIM)
				.build());

			long profit = viewer.alchProfit(entry.getItemId()) * entry.getQuantity();
			panel.getChildren().add(LineComponent.builder()
				.left(config.natureRuneCost() > 0 ? "Alch profit" : "Alch value")
				.leftColor(BankStyle.TEXT_DIM)
				.right(BankStyle.gp(profit) + " gp")
				.rightColor(profit < 0 ? BankStyle.QUANTITY_LOW : BankStyle.TEXT_DIM)
				.build());
		}

		if (GroupBankViewer.TAB_ALL.equals(viewer.getActiveTab()))
		{
			Map<String, Long> owners = viewer.ownersOf(entry.getItemId());
			for (Map.Entry<String, Long> owner : owners.entrySet())
			{
				GroupMember member = groupState.getMember(owner.getKey());
				panel.getChildren().add(LineComponent.builder()
					.left(owner.getKey())
					.leftColor(member != null ? member.getColour() : BankStyle.TEXT_DIM)
					.right(BankStyle.commas(owner.getValue()))
					.rightColor(BankStyle.TEXT_DIM)
					.build());
			}
		}

		// PanelComponent sizes its background from the child dimensions measured during the
		// previous render, and this panel is built fresh every frame, so on its only render
		// that size is zero and the background never appears. Rendering once against a
		// scratch context clipped to nothing measures the children without drawing anything,
		// leaving the real render with a correctly sized background.
		Graphics2D scratch = (Graphics2D) graphics.create();
		try
		{
			scratch.setClip(0, 0, 0, 0);
			panel.render(scratch);
		}
		finally
		{
			scratch.dispose();
		}

		tooltipManager.add(new Tooltip(new TintedTooltip(panel)));
	}

	// ------------------------------------------------------------------
	// Hit testing, used by GroupBankInput
	// ------------------------------------------------------------------

	/**
	 * The scroll row a click at this height on the scrollbar corresponds to.
	 * <p>
	 * The thumb is centred on the pointer, so grabbing it anywhere and dragging tracks the
	 * mouse instead of jumping. Kept beside {@link #drawScrollbar} because the two share the
	 * same thumb geometry.
	 */
	int scrollRowForY(int canvasY)
	{
		Rectangle track = hits.scrollbar;
		int totalRows = viewer.getRows().size();
		int maxScroll = totalRows - VISIBLE_ROWS;
		if (track.height <= 0 || maxScroll <= 0)
		{
			return 0;
		}

		int thumbHeight = Math.max(12, track.height * VISIBLE_ROWS / totalRows);
		int travel = Math.max(1, track.height - thumbHeight);
		int offset = canvasY - track.y - thumbHeight / 2;

		long row = Math.round((double) offset / travel * maxScroll);
		return (int) Math.max(0, Math.min(maxScroll, row));
	}

	/** The most recently drawn frame's hit boxes. Never null. */
	HitBoxes getHits()
	{
		return hits;
	}

	/**
	 * One frame's clickable regions, in canvas coordinates. Immutable once constructed so it
	 * can be handed to the AWT thread without locking.
	 */
	static final class HitBoxes
	{
		static final HitBoxes EMPTY = new HitBoxes(
			new Rectangle(), new Rectangle(), new Rectangle(), new Rectangle(), new Rectangle(),
			java.util.Collections.emptyList());

		final Rectangle window;
		final Rectangle close;
		final Rectangle search;
		final Rectangle grid;
		final Rectangle scrollbar;
		final List<TabHit> tabs;

		HitBoxes(Rectangle window, Rectangle close, Rectangle search, Rectangle grid,
			Rectangle scrollbar, List<TabHit> tabs)
		{
			this.window = window;
			this.close = close;
			this.search = search;
			this.grid = grid;
			this.scrollbar = scrollbar;
			this.tabs = java.util.Collections.unmodifiableList(tabs);
		}
	}

	private static Rectangle toCanvas(Rectangle local, java.awt.Point origin)
	{
		return new Rectangle(local.x + origin.x, local.y + origin.y, local.width, local.height);
	}

	@Nullable
	private Color colourForTab(String tab)
	{
		if (GroupBankViewer.TAB_ALL.equals(tab) || GroupBankViewer.TAB_SHARED.equals(tab))
		{
			return BankStyle.TEXT;
		}
		GroupMember member = groupState.getMember(tab);
		return member != null ? member.getColour() : BankStyle.TEXT;
	}

	private static String abbreviate(String text, FontMetrics metrics, int maxWidth)
	{
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String result = text;
		while (result.length() > 1 && metrics.stringWidth(result + "…") > maxWidth)
		{
			result = result.substring(0, result.length() - 1);
		}
		return result + "…";
	}

	private static boolean blink()
	{
		return (System.currentTimeMillis() / 500) % 2 == 0;
	}

	static final class TabHit
	{
		final String tab;
		final Rectangle bounds;

		TabHit(String tab, Rectangle bounds)
		{
			this.tab = tab;
			this.bounds = bounds;
		}
	}
}

package com.groupironmencompanion.bank;

import java.awt.Color;
import java.text.NumberFormat;
import java.util.Locale;

/** Shared colours and number formatting for the group bank window. */
final class BankStyle
{
	static final Color BACKGROUND = new Color(45, 39, 30, 240);
	static final Color TITLE_BACKGROUND = new Color(30, 26, 20, 250);
	static final Color BORDER = new Color(94, 82, 62);
	static final Color TEXT = new Color(255, 217, 148);
	static final Color TEXT_DIM = new Color(170, 155, 125);
	static final Color TAB_ACTIVE = new Color(78, 68, 52, 255);
	static final Color TAB_IDLE = new Color(38, 33, 26, 255);
	static final Color HOVER = new Color(255, 255, 255, 40);
	static final Color SEARCH_BACKGROUND = new Color(24, 21, 16, 255);

	static final Color QUANTITY_LOW = new Color(255, 255, 0);
	static final Color QUANTITY_MID = Color.WHITE;
	static final Color QUANTITY_HIGH = new Color(0, 255, 128);

	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private BankStyle()
	{
	}

	static String commas(long value)
	{
		return NUMBERS.format(value);
	}

	/** The abbreviated quantity the game itself draws on a stack. */
	static String shortQuantity(long quantity)
	{
		if (quantity >= 10_000_000)
		{
			return (quantity / 1_000_000) + "M";
		}
		if (quantity >= 100_000)
		{
			return (quantity / 1000) + "K";
		}
		return Long.toString(quantity);
	}

	/** The colour the game uses for a stack size, by magnitude. */
	static Color quantityColour(long quantity)
	{
		if (quantity >= 10_000_000)
		{
			return QUANTITY_HIGH;
		}
		if (quantity >= 100_000)
		{
			return QUANTITY_MID;
		}
		return QUANTITY_LOW;
	}

	/** Compact gp, e.g. 4.2m. */
	static String gp(long value)
	{
		if (value < 0)
		{
			return "-" + gp(-value);
		}
		if (value >= 1_000_000_000L)
		{
			return String.format(Locale.ENGLISH, "%.1fb", value / 1_000_000_000.0);
		}
		if (value >= 1_000_000L)
		{
			return String.format(Locale.ENGLISH, "%.1fm", value / 1_000_000.0);
		}
		if (value >= 1000L)
		{
			return String.format(Locale.ENGLISH, "%.1fk", value / 1000.0);
		}
		return Long.toString(value);
	}
}

package com.groupironmencompanion.bank;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;

/**
 * Mouse and keyboard handling for the group bank window.
 * <p>
 * Input is only ever consumed while the window is open and the pointer is inside it, or on
 * the small Group tab. Every action it can take is client-side: opening and closing the
 * plugin's own overlay, switching tab, scrolling, and typing into the plugin's own search
 * box. No input is translated into anything the game sends to the server.
 */
@Singleton
public class GroupBankInput extends MouseAdapter implements MouseWheelListener
{
	private static final int SCROLL_ROWS = 3;

	@Inject
	private GroupBankViewer viewer;

	@Inject
	private GroupBankOverlay overlay;

	@Inject
	private GroupBankTabOverlay tabOverlay;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	/** Set while the scrollbar is being dragged, so movement keeps scrolling after the press. */
	private boolean draggingScrollbar;

	// ------------------------------------------------------------------
	// Mouse
	// ------------------------------------------------------------------

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (!config.bankViewer())
		{
			return event;
		}

		// Alt is RuneLite's overlay drag modifier; leave those clicks alone so the window
		// stays repositionable like any other overlay.
		if (event.isAltDown())
		{
			return event;
		}

		java.awt.Point point = event.getPoint();

		Rectangle tab = tabOverlay.getHit();
		if (tab != null && tab.contains(point))
		{
			if (!viewer.isOpen())
			{
				openBesideBank();
			}
			else
			{
				viewer.setOpen(false);
			}
			event.consume();
			return event;
		}

		if (!viewer.isOpen())
		{
			return event;
		}

		// One snapshot for the whole decision, so every test below sees the same frame.
		GroupBankOverlay.HitBoxes hits = overlay.getHits();

		if (!hits.window.contains(point))
		{
			// A click elsewhere dismisses the search prompt but still reaches the game.
			clientThread.invoke(this::closeSearch);
			return event;
		}

		if (hits.scrollbar.contains(point))
		{
			draggingScrollbar = true;
			viewer.setScrollRow(overlay.scrollRowForY(point.y));
			event.consume();
			return event;
		}

		if (hits.close.contains(point))
		{
			clientThread.invoke(() ->
			{
				closeSearch();
				viewer.setOpen(false);
			});
			event.consume();
			return event;
		}

		for (GroupBankOverlay.TabHit hit : hits.tabs)
		{
			if (hit.bounds.contains(point))
			{
				viewer.setActiveTab(hit.tab);
				clientThread.invoke(this::closeSearch);
				event.consume();
				return event;
			}
		}

		boolean onSearchBox = hits.search.contains(point);
		clientThread.invoke(() ->
		{
			if (onSearchBox)
			{
				openSearch();
			}
			else
			{
				closeSearch();
			}
		});

		// Swallow anything else inside the window so clicks do not fall through to the game.
		event.consume();
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		return swallowInsideWindow(event);
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		draggingScrollbar = false;
		return swallowInsideWindow(event);
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (!draggingScrollbar)
		{
			return event;
		}
		if (!config.bankViewer() || !viewer.isOpen())
		{
			draggingScrollbar = false;
			return event;
		}

		// Track the pointer even once it leaves the bar, which is how scrollbars behave
		// everywhere else; the row is clamped, so dragging past either end just pins it.
		viewer.setScrollRow(overlay.scrollRowForY(event.getY()));
		event.consume();
		return event;
	}

	private MouseEvent swallowInsideWindow(MouseEvent event)
	{
		if (config.bankViewer() && viewer.isOpen() && !event.isAltDown()
			&& overlay.getHits().window.contains(event.getPoint()))
		{
			event.consume();
		}
		return event;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		if (!config.bankViewer() || !viewer.isOpen())
		{
			return event;
		}
		if (!overlay.getHits().grid.contains(event.getPoint()))
		{
			return event;
		}

		int rows = Math.max(1, viewer.getRows().size());
		int maxScroll = Math.max(0, rows - GroupBankOverlay.VISIBLE_ROWS);
		int next = viewer.getScrollRow() + (event.getWheelRotation() > 0 ? SCROLL_ROWS : -SCROLL_ROWS);
		viewer.setScrollRow(Math.max(0, Math.min(maxScroll, next)));

		event.consume();
		return event;
	}

	// ------------------------------------------------------------------
	// Searching
	// ------------------------------------------------------------------

	/**
	 * Opens the game's own chatbox text input for the search box.
	 * <p>
	 * Capturing keystrokes directly does not work here. RuneLite's key remapping consumes
	 * W, A, S and D for camera movement before any other listener sees them, and KeyManager
	 * dispatches in registration order with no way to get in front of it. Anyone using WASD
	 * camera could not type those letters into the search.
	 * <p>
	 * Going through the chatbox solves it at the source: key remapping already stands down
	 * while the chatbox is taking input, so every letter arrives, and camera keys keep
	 * working normally the rest of the time because nothing is being intercepted at all.
	 */
	private void openSearch()
	{
		viewer.setSearchFocused(true);
		chatboxPanelManager.openTextInput("Search group bank")
			.value(viewer.getFilter())
			.onChanged(value -> viewer.setFilter(value.trim()))
			.onClose(() -> viewer.setSearchFocused(false))
			.build();
	}

	/** Closes the search prompt if it is the thing currently open. */
	private void closeSearch()
	{
		if (viewer.isSearchFocused())
		{
			viewer.setSearchFocused(false);
			chatboxPanelManager.close();
		}
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	/**
	 * Opens the window, placing it only if the user has never moved it.
	 * <p>
	 * The window is opened first and unconditionally, because this is called from the AWT
	 * thread (the hotkey and the Group tab) as well as from game events. Working out where to
	 * put it means reading the bank widget, which is only legal on the client thread, so that
	 * part hops threads. Doing it inline was why the hotkey and the tab appeared to do
	 * nothing: the client call threw before the window was ever opened.
	 * <p>
	 * A remembered position always wins. RuneLite persists it when you alt-drag the overlay
	 * and restores it on startup, so re-docking on every open would throw that away.
	 */
	/**
	 * Closes the window and any search prompt with it. Safe to call from any thread, so the
	 * hotkey and the game events that dismiss the window can share one path.
	 */
	public void closeAll()
	{
		clientThread.invoke(() ->
		{
			closeSearch();
			viewer.setOpen(false);
		});
	}

	public void openBesideBank()
	{
		viewer.setOpen(true);

		if (overlay.getPreferredLocation() == null)
		{
			clientThread.invoke(() ->
			{
				if (overlay.getPreferredLocation() == null)
				{
					overlay.setPreferredLocation(tabOverlay.defaultLocation(
						GroupBankOverlay.WIDTH, overlay.getWindowSize().height));
				}
			});
		}
	}
}

package com.groupironmencompanion.bank;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small "Group" tab drawn alongside the bank while it is open, so the group bank viewer is
 * one click away without having to remember the hotkey.
 * <p>
 * The tab is drawn by the plugin outside the bank window's own rectangle. No widget is
 * created, reparented, resized or unhidden, and no menu entry is added: clicking it only
 * toggles a plugin overlay, so nothing is ever sent to the server.
 */
@Singleton
public class GroupBankTabOverlay extends Overlay
{
	private static final int TAB_WIDTH = 52;
	private static final int TAB_HEIGHT = 22;
	private static final int GAP = 3;

	/**
	 * Keeps the viewer clear of the top-left corner, where the client draws the click-to-move
	 * and menu-target text that would otherwise sit on top of it.
	 */
	private static final int TOP_MARGIN = 24;
	private static final int SIDE_MARGIN = 4;

	private static final Font FONT = new Font(Font.SANS_SERIF, Font.BOLD, 11);

	@Inject
	private Client client;

	@Inject
	private GroupBankViewer viewer;

	@Inject
	private GroupIronmenCompanionConfig config;

	/** Where the tab was last drawn, in canvas coordinates, or null when it is not shown. */
	private Rectangle hit;

	@Inject
	public GroupBankTabOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		hit = null;

		if (!config.bankViewer() || !config.bankShowTab())
		{
			return null;
		}

		Rectangle bankBounds = bankBounds();
		if (bankBounds == null)
		{
			return null;
		}

		Rectangle tab = place(bankBounds);
		hit = tab;

		Point mouse = client.getMouseCanvasPosition();
		boolean hovered = mouse != null && tab.contains(mouse.getX(), mouse.getY());
		boolean active = viewer.isOpen();

		graphics.setColor(active ? BankStyle.TAB_ACTIVE : BankStyle.TITLE_BACKGROUND);
		graphics.fillRect(tab.x, tab.y, tab.width, tab.height);

		if (hovered)
		{
			graphics.setColor(BankStyle.HOVER);
			graphics.fillRect(tab.x, tab.y, tab.width, tab.height);
		}

		graphics.setColor(BankStyle.BORDER);
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawRect(tab.x, tab.y, tab.width - 1, tab.height - 1);

		graphics.setFont(FONT);
		graphics.setColor(active || hovered ? Color.WHITE : BankStyle.TEXT);
		int textWidth = graphics.getFontMetrics().stringWidth("Group");
		graphics.drawString("Group", tab.x + (tab.width - textWidth) / 2, tab.y + 15);

		return null;
	}

	/**
	 * Sits the tab just outside the bank window, on whichever side has room, so it never
	 * covers any part of the bank.
	 */
	private Rectangle place(Rectangle bank)
	{
		int y = bank.y + 4;

		int right = bank.x + bank.width + GAP;
		if (right + TAB_WIDTH <= client.getCanvasWidth())
		{
			return new Rectangle(right, y, TAB_WIDTH, TAB_HEIGHT);
		}

		int left = bank.x - GAP - TAB_WIDTH;
		if (left >= 0)
		{
			return new Rectangle(left, y, TAB_WIDTH, TAB_HEIGHT);
		}

		// Nowhere beside it fits, so sit directly above the bank instead.
		return new Rectangle(bank.x, Math.max(0, bank.y - GAP - TAB_HEIGHT), TAB_WIDTH, TAB_HEIGHT);
	}

	@Nullable
	private Rectangle bankBounds()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden())
		{
			return null;
		}
		Rectangle bounds = bank.getBounds();
		return bounds == null || bounds.width <= 0 ? null : bounds;
	}

	/** The tab's canvas rectangle, or null when it is not currently drawn. */
	@Nullable
	Rectangle getHit()
	{
		return hit;
	}

	/**
	 * Where the viewer should appear the very first time it is opened, before the user has
	 * dragged it anywhere. Prefers the left of the bank, and pins to the left edge of the
	 * canvas when the bank is too wide to sit beside, which at least puts it somewhere
	 * predictable and out of the way of the bank's own controls.
	 * <p>
	 * Reads the bank widget, so this must be called on the client thread.
	 */
	java.awt.Point defaultLocation(int windowWidth, int windowHeight)
	{
		int canvasWidth = client.getCanvasWidth();
		int canvasHeight = client.getCanvasHeight();
		Rectangle bank = bankBounds();

		if (bank == null)
		{
			return clamp((canvasWidth - windowWidth) / 2, (canvasHeight - windowHeight) / 2,
				windowWidth, windowHeight, canvasWidth, canvasHeight);
		}

		int left = bank.x - GAP - windowWidth;
		int right = bank.x + bank.width + GAP;

		int x;
		if (left >= SIDE_MARGIN)
		{
			x = left;
		}
		else if (right + windowWidth + SIDE_MARGIN <= canvasWidth)
		{
			x = right;
		}
		else
		{
			// Neither side fits, which is normal in fixed mode where the bank fills the
			// screen. Pin to the left edge; the position is remembered once moved.
			x = SIDE_MARGIN;
		}

		return clamp(x, bank.y, windowWidth, windowHeight, canvasWidth, canvasHeight);
	}

	/** True while the player's own bank interface is open. Client thread only. */
	boolean isBankOpen()
	{
		return bankBounds() != null;
	}

	/** Keeps the window fully on the canvas and out of the top-left text area. */
	private static java.awt.Point clamp(int x, int y, int width, int height, int canvasWidth, int canvasHeight)
	{
		int clampedX = Math.max(SIDE_MARGIN, Math.min(x, canvasWidth - width - SIDE_MARGIN));
		int clampedY = Math.max(TOP_MARGIN, Math.min(y, canvasHeight - height - SIDE_MARGIN));
		return new java.awt.Point(clampedX, clampedY);
	}
}

package com.groupironmencompanion.bank;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import com.groupironmencompanion.data.ItemStack;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.game.ItemManager;

/**
 * The state behind the read-only group bank window: which tab is open, what has been typed
 * into the search box, how far it is scrolled, and the laid-out rows to draw.
 * <p>
 * Nothing here can move an item. The plugin has no way to withdraw, deposit or otherwise act
 * on anything shown; it only reads item ids and quantities that your group members' own
 * clients published to your shared server.
 */
@Singleton
public class GroupBankViewer
{
	public static final String TAB_ALL = "All";
	public static final String TAB_SHARED = "Group Storage";

	/** Items per row in the grid. */
	public static final int COLUMNS = 8;

	@Inject
	private GroupState groupState;

	@Inject
	private ItemManager itemManager;

	@Inject
	private com.groupironmencompanion.GroupIronmenCompanionConfig config;

	@Getter
	private volatile boolean open;

	@Getter
	private String activeTab = TAB_ALL;

	@Getter
	private String filter = "";

	@Getter
	@Setter
	private int scrollRow;

	@Getter
	private boolean searchFocused;

	/** Bumped whenever something that affects the laid-out rows changes. */
	private volatile boolean dirty = true;

	@Getter
	private List<Row> rows = new ArrayList<>();

	@Getter
	private List<String> tabs = new ArrayList<>();

	@Getter
	private int visibleItemCount;

	@Getter
	private long visibleValue;

	// ------------------------------------------------------------------
	// Window state
	// ------------------------------------------------------------------

	public void setOpen(boolean open)
	{
		if (this.open != open)
		{
			this.open = open;
			this.searchFocused = open && !filter.isEmpty();
			markDirty();
		}
	}

	public void toggle()
	{
		setOpen(!open);
	}

	public void setActiveTab(String tab)
	{
		if (!activeTab.equals(tab))
		{
			activeTab = tab;
			scrollRow = 0;
			markDirty();
		}
	}

	public void setFilter(String filter)
	{
		String next = filter == null ? "" : filter;
		if (!this.filter.equals(next))
		{
			this.filter = next;
			scrollRow = 0;
			markDirty();
		}
	}

	public void setSearchFocused(boolean focused)
	{
		this.searchFocused = focused;
	}

	public void markDirty()
	{
		dirty = true;
	}

	public void reset()
	{
		open = false;
		activeTab = TAB_ALL;
		filter = "";
		scrollRow = 0;
		searchFocused = false;
		rows = new ArrayList<>();
		tabs = new ArrayList<>();
		markDirty();
	}

	// ------------------------------------------------------------------
	// Layout
	// ------------------------------------------------------------------

	/**
	 * Recomputes the tab list and the laid-out rows if anything changed. Must run on the
	 * client thread because it reads item compositions.
	 */
	public void rebuildIfNeeded()
	{
		if (!dirty)
		{
			return;
		}
		dirty = false;

		List<GroupMember> members = groupState.getMembers();

		List<String> newTabs = new ArrayList<>();
		newTabs.add(TAB_ALL);
		for (GroupMember member : members)
		{
			newTabs.add(member.getName());
		}
		newTabs.add(TAB_SHARED);
		tabs = newTabs;

		if (!newTabs.contains(activeTab))
		{
			activeTab = TAB_ALL;
			scrollRow = 0;
		}

		List<Entry> entries = TAB_ALL.equals(activeTab)
			? aggregateEntries()
			: memberEntries(activeTab);

		rows = layout(entries);

		int count = 0;
		long value = 0;
		for (Entry entry : entries)
		{
			if (!entry.header)
			{
				count++;
				value += alchProfit(entry.itemId) * entry.quantity;
			}
		}
		visibleItemCount = count;
		visibleValue = value;

		int maxScroll = Math.max(0, rows.size() - 1);
		if (scrollRow > maxScroll)
		{
			scrollRow = maxScroll;
		}
	}

	/** Everything the whole group owns, summed per item and sorted by total value. */
	private List<Entry> aggregateEntries()
	{
		// Group storage is already part of the totals; adding it here counted it twice.
		Map<Integer, Long> totals = groupState.getGroupTotals();

		List<Entry> entries = new ArrayList<>(totals.size());
		for (Map.Entry<Integer, Long> total : totals.entrySet())
		{
			if (matches(total.getKey()))
			{
				entries.add(Entry.item(total.getKey(), total.getValue(), null));
			}
		}

		// Value is looked up once per entry rather than on every comparison; a whole group's
		// bank can run to thousands of stacks.
		Map<Integer, Long> values = new HashMap<>(entries.size());
		for (Entry entry : entries)
		{
			values.put(entry.itemId, alchProfit(entry.itemId) * entry.quantity);
		}
		entries.sort(Comparator.comparingLong((Entry e) -> values.getOrDefault(e.itemId, 0L)).reversed());
		return entries;
	}

	/** One member's holdings, split into the containers they came from. */
	private List<Entry> memberEntries(String tab)
	{
		GroupMember member = TAB_SHARED.equals(tab)
			? groupState.getSharedBank()
			: groupState.getMember(tab);

		if (member == null)
		{
			return new ArrayList<>();
		}

		Map<String, List<ItemStack>> sections = new LinkedHashMap<>();
		if (TAB_SHARED.equals(tab))
		{
			sections.put("Group storage", member.getBank());
		}
		else
		{
			// Bank goes last on purpose. It dwarfs everything else, so leading with it would
			// bury the small containers behind a long scroll.
			sections.put("Inventory", member.getInventory());
			sections.put("Equipment", member.getEquipment());
			sections.put("Rune pouch", member.getRunePouch());
			sections.put("Quiver", member.getQuiver());
			sections.put("Seed vault", member.getSeedVault());
			sections.put("Bank", member.getBank());
		}

		List<Entry> entries = new ArrayList<>();
		for (Map.Entry<String, List<ItemStack>> section : sections.entrySet())
		{
			List<Entry> items = new ArrayList<>();
			for (ItemStack item : section.getValue())
			{
				if (!item.isEmpty() && matches(item.getId()))
				{
					items.add(Entry.item(item.getId(), item.getQuantity(), member.getName()));
				}
			}
			if (!items.isEmpty())
			{
				entries.add(Entry.header(section.getKey()));
				entries.addAll(items);
			}
		}
		return entries;
	}

	/** Packs entries into rows, with headers always taking a row of their own. */
	private List<Row> layout(List<Entry> entries)
	{
		List<Row> result = new ArrayList<>();
		List<Entry> current = new ArrayList<>();

		for (Entry entry : entries)
		{
			if (entry.header)
			{
				if (!current.isEmpty())
				{
					result.add(Row.items(current));
					current = new ArrayList<>();
				}
				result.add(Row.header(entry.label));
				continue;
			}

			current.add(entry);
			if (current.size() == COLUMNS)
			{
				result.add(Row.items(current));
				current = new ArrayList<>();
			}
		}

		if (!current.isEmpty())
		{
			result.add(Row.items(current));
		}
		return result;
	}

	private boolean matches(int itemId)
	{
		if (filter.isEmpty())
		{
			return true;
		}
		String name = itemName(itemId);
		return name != null && name.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT));
	}

	/**
	 * What an item alchs for. Group ironmen cannot use the Grand Exchange, so this is the
	 * number that actually means something to them.
	 */
	public long alchValue(int itemId)
	{
		try
		{
			return Math.max(0, itemManager.getItemComposition(itemId).getHaPrice());
		}
		catch (Exception e)
		{
			return 0;
		}
	}

	/**
	 * Profit from alching one of an item, after paying for the nature rune. Negative for
	 * anything that alchs for less than the rune costs, which is worth seeing rather than
	 * hiding. With the cost set to zero this is just the raw alch value.
	 */
	public long alchProfit(int itemId)
	{
		return alchValue(itemId) - Math.max(0, config.natureRuneCost());
	}

	@Nullable
	public String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (Exception e)
		{
			return null;
		}
	}

	/**
	 * Which members hold a given item and how many, used for the hover breakdown on the
	 * aggregate tab.
	 */
	public Map<String, Long> ownersOf(int itemId)
	{
		Map<String, Long> owners = new LinkedHashMap<>();
		for (GroupMember member : groupState.getMembers())
		{
			long quantity = 0;
			quantity += count(member.getBank(), itemId);
			quantity += count(member.getInventory(), itemId);
			quantity += count(member.getEquipment(), itemId);
			quantity += count(member.getRunePouch(), itemId);
			quantity += count(member.getSeedVault(), itemId);
			quantity += count(member.getQuiver(), itemId);
			if (quantity > 0)
			{
				owners.put(member.getName(), quantity);
			}
		}

		GroupMember shared = groupState.getSharedBank();
		if (shared != null)
		{
			long quantity = count(shared.getBank(), itemId);
			if (quantity > 0)
			{
				owners.put(TAB_SHARED, quantity);
			}
		}
		return owners;
	}

	private static long count(List<ItemStack> items, int itemId)
	{
		long total = 0;
		for (ItemStack item : items)
		{
			if (item.getId() == itemId)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	// ------------------------------------------------------------------
	// Row and entry types
	// ------------------------------------------------------------------

	/** One item cell, or a section heading. */
	public static final class Entry
	{
		final boolean header;
		final String label;
		final int itemId;
		final long quantity;
		final String owner;

		private Entry(boolean header, String label, int itemId, long quantity, String owner)
		{
			this.header = header;
			this.label = label;
			this.itemId = itemId;
			this.quantity = quantity;
			this.owner = owner;
		}

		static Entry header(String label)
		{
			return new Entry(true, label, 0, 0, null);
		}

		static Entry item(int itemId, long quantity, String owner)
		{
			return new Entry(false, null, itemId, quantity, owner);
		}

		public int getItemId()
		{
			return itemId;
		}

		public long getQuantity()
		{
			return quantity;
		}

		@Nullable
		public String getOwner()
		{
			return owner;
		}
	}

	/** One drawn line: either a heading or a row of items. */
	public static final class Row
	{
		private final String header;
		private final List<Entry> items;

		private Row(String header, List<Entry> items)
		{
			this.header = header;
			this.items = items;
		}

		static Row header(String text)
		{
			return new Row(text, null);
		}

		static Row items(List<Entry> items)
		{
			return new Row(null, new ArrayList<>(items));
		}

		public boolean isHeader()
		{
			return header != null;
		}

		public String getHeader()
		{
			return header;
		}

		public List<Entry> getItems()
		{
			return items;
		}
	}
}
